                    payment.get("date"));
            maxPaymentId = Math.max(maxPaymentId, id);
        }
        if (maxPaymentId > 0) {
            jdbc.execute("ALTER TABLE payments ALTER COLUMN id RESTART WITH " + (maxPaymentId + 1));
